using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    public static IEnumerable<object[]> GoldenScenarios()
    {
        var json = File.ReadAllText(GoldenPath);
        var scenarios = JsonSerializer.Deserialize<List<GoldenScenario>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        foreach (var scenario in scenarios)
        {
            yield return new object[] { scenario.Id, scenario };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenScenarios))]
    public async Task EvaluateScenario(string id, GoldenScenario scenario)
    {
        // The rubric is available for evaluators that need custom grading criteria.
        var rubric = await File.ReadAllTextAsync(RubricPath);

        // Placeholder: invoke the agent under test with scenario.UserMessage
        // and collect the response. Replace with actual agent invocation.
        var agentResponse = await InvokeAgentAsync(scenario.UserMessage);

        Assert.NotNull(agentResponse);
        Assert.False(string.IsNullOrWhiteSpace(agentResponse),
            $"Scenario '{id}' produced an empty response.");
    }

    private static Task<string> InvokeAgentAsync(string userMessage)
    {
        // TODO: Replace with actual agent invocation via the AppHost.
        // This stub returns a placeholder so the harness compiles and runs.
        return Task.FromResult($"[stub response for: {userMessage}]");
    }
}

